steps.sql:
SELECT DATE '2025-03-12' - DATE '2025-03-10' FROM dual;
-> 2                              (un NOMBRE de jours)

SELECT TIMESTAMP '2025-03-12 18:00:00' - TIMESTAMP '2025-03-12 14:30:00' FROM dual;
-> +00 03:30:00.000000             (un INTERVAL)

SELECT TIMESTAMP '2025-03-12 12:00:00 UTC' AT TIME ZONE 'Africa/Lagos' FROM dual;
-> 12/03/2025 13:00:00 +01:00

SELECT TIMESTAMP '2025-03-12 12:00:00 UTC' AT TIME ZONE 'America/New_York' FROM dual;
-> 12/03/2025 08:00:00 -04:00     (New York est déjà à l'heure d'été le 12 mars)

SELECT TIMESTAMP '2025-03-12 12:00:00 UTC' AT TIME ZONE 'Asia/Tokyo' FROM dual;
-> 12/03/2025 21:00:00 +09:00
